    secondary: {
      main: '#42A5F5',
    },
    background: {
      default: 'transparent',
      paper: 'rgba(255, 255, 255, 0.9)', // Transparencia en las cards
    },
    text: {
      primary: '#1a1a1a',
      secondary: '#424242',
    },
    success: {
      main: '#2E7D32',
    },
    warning: {
      main: '#F57C00',
    },
    error: {
      main: '#C62828',
    },
  },
  typography: {
